-- Unity Catalog: grant data access to a group (run in a SQL editor / notebook)
GRANT USE CATALOG ON CATALOG main TO `analysts`;
GRANT USE SCHEMA  ON SCHEMA  main.sales TO `analysts`;
GRANT SELECT      ON SCHEMA  main.sales TO `analysts`;

-- Grant write access on a single table to the engineering group
GRANT SELECT, MODIFY ON TABLE main.sales.orders TO `data_engineers`;

-- Inspect and revoke
SHOW GRANTS ON SCHEMA main.sales;
REVOKE SELECT ON SCHEMA main.sales FROM `contractors`;

